      "За счёт глубокого понимания продукта и точного подбора аудитории часть проектов даёт конверсию до 25–30% из целевых контактов во встречу.": "Due to a deep understanding of the product and precise selection of the audience, some projects achieve a conversion of up to 25–30% from target contacts to meetings.",
      "Заказчик видит, как рынок реагирует на продукт: какие аргументы работают, какие сегменты откликаются, что мешает интересу и где требуется усилить предложение.": "The customer sees how the market reacts to the product: which arguments work, which segments respond, what hinders interest and where the offer needs to be strengthened.",
      "Заказчик получает не только контакты, но и понимание, какие сегменты рынка реагируют лучше, где интерес выше, а где предложение вызывает слабую реакцию.": "The customer receives not only contacts, but also an understanding of which market segments respond better, where interest is higher, and where the offer causes a weak reaction.",
