      "Можно ли работать только по одному сегменту?": "Is it possible to work on only one segment?",
      "Мы ищем компании, которым продукт может быть реально нужен: по отрасли, роли, размеру, событию и закупочной логике.": "We are looking for companies that may really need the product: by industry, role, size, event and purchasing logic.",
      "Мы продаём смыслами: разбираемся в продукте, ведём содержательный разговор с ЛПР и доводим до встречи, а не до отметки в отчёте.": "We sell with meaning: we understand the product, have a meaningful conversation with the decision-maker and bring it to a meeting, and not to a mark in the report.",
      "На каких рынках работаете?": "What markets do you operate in?",
      "Назначаем встречу с вашей командой и передаём контекст: кто клиент, в чём интерес, какие вопросы возникли.": "We set up a meeting with your team and convey the context: who the client is, what is the interest, what questions have arisen.",
      "Назначенные встречи": "Scheduled appointments",
      "Найти дистрибьютора": "Find a distributor",
      "Написать в AXCEND": "Contact AXCEND",
      "Находим дилеров, оптовиков, торговые дома": "We find dealers, wholesalers, trading houses",
      "Находим первых клиентов и партнёров": "We find our first clients and partners",
      "Наши менеджеры не работают по шаблону. В этом одно из ключевых отличий AXCEND. Благодаря опыту в консалтинге и B2B продажах наши менеджеры понимают как устроен рынок, разбираются даже в сложных продуктах, четко понимая интересы бизнеса, постепенно доводя контакт до готовности к встрече с заказчиком.": "Our managers do not work according to a template. This is one of the key differences between AXCEND. Thanks to experience in consulting and B2B sales, our managers understand how the market works, understand even complex products, clearly understand the interests of the business, gradually bringing contact to readiness for a meeting with the customer.",
      "Не случайный список компаний, а отобранная база организаций, которым продукт заказчика может быть релевантен по отрасли, размеру, географии, роли и признакам возможной потребности.": "Not a random list of companies, but a selected database of organizations to which the customer’s product may be relevant by industry, size, geography, role and signs of possible need.",
