      "Перед контактом с рынком нужно понять продукт, экономику сделки, аргументы для руководителей и возможные возражения.": "Before contacting the market, you need to understand the product, the economics of the transaction, the arguments for managers and possible objections.",
      "Перед стартом продаж изучаем рынок, конкурентов и целевую аудиторию. Смотрим, какие компании нуждаются в данном продукте, как сейчас продают аналогичные решения и какие аргументы сильнее всего работают в переговорах.": "Before starting sales, we study the market, competitors and target audience. We look at which companies need this product, how they are currently selling similar solutions, and which arguments work most strongly in negotiations.",
      "Передаём встречи и горячие лиды": "We transfer meetings and hot leads",
