      "У нас входящие сыплются, а отвечать некому. Плюс по холодке надо звонить — а сил на это нет. Заберите всё, верните уже закрытые сделки.": "Our inboxes are flooding, but there is no one to answer. Plus, you have to call when it’s cold - but you don’t have the strength to do it. Take everything, return already closed transactions.",
      "Узбекистан": "Uzbekistan",
      "УЛЦ «Качество»": "ULC \"Quality\"",
      "Фиксируем обязательства письменно: клиент заранее понимает, какой результат должен быть достигнут.": "We fix the obligations in writing: the client understands in advance what result should be achieved.",
      "Финансы": "Finance",
