      "языков продаж": "sales languages",
      "AXCEND выстраивает полный цикл B2B-продаж: находим потенциальных клиентов, выходим на профильных руководителей, ведём переговоры, фиксируем результат в CRM и передаём готовых к сделке клиентов.": "AXCEND builds a full cycle of B2B sales: we find potential clients, contact relevant managers, negotiate, record the results in CRM and transfer clients who are ready for a deal.",
      "AXCEND передаёт не просто контакты, а компании, которые поняли предложение, проявили интерес и согласились обсудить его с командой заказчика.": "AXCEND transfers not just contacts, but companies that understood the proposal, showed interest and agreed to discuss it with the customer’s team.",
