      "Перед контактом с рынком нужно понять продукт, экономику сделки, аргументы для руководителей и возможные возражения.": "Bevor Sie den Markt kontaktieren, müssen Sie das Produkt, die Wirtschaftlichkeit der Transaktion, die Argumente für Manager und mögliche Einwände verstehen.",
      "Перед стартом продаж изучаем рынок, конкурентов и целевую аудиторию. Смотрим, какие компании нуждаются в данном продукте, как сейчас продают аналогичные решения и какие аргументы сильнее всего работают в переговорах.": "Bevor wir mit dem Verkauf beginnen, untersuchen wir den Markt, die Wettbewerber und die Zielgruppe. Wir schauen uns an, welche Unternehmen dieses Produkt benötigen, wie sie derzeit ähnliche Lösungen verkaufen und welche Argumente in Verhandlungen am stärksten wirken.",
      "Передаём встречи и горячие лиды": "Wir übertragen Meetings und Hot Leads",
      "Передаёте ли CRM и данные?": "Übertragen Sie CRM und Daten?",
      "Передаётся информация: кто заинтересовался, в чём причина интереса, какие вопросы возникли, какие возражения были озвучены и что важно учесть на встрече.": "Es werden Informationen vermittelt: Wer ist interessiert, was ist der Grund für das Interesse, welche Fragen sind aufgetreten, welche Einwände wurden geäußert und was ist bei der Besprechung zu beachten?",
