      "У нас входящие сыплются, а отвечать некому. Плюс по холодке надо звонить — а сил на это нет. Заберите всё, верните уже закрытые сделки.": "Unsere Posteingänge werden überschwemmt, aber es gibt niemanden, der antworten kann. Außerdem muss man anrufen, wenn es kalt ist – aber man hat nicht die Kraft dazu. Nehmen Sie alles, geben Sie bereits abgeschlossene Transaktionen zurück.",
      "Узбекистан": "Usbekistan",
