      "Формируем базу клиентов, очищаем её от нерелевантных компаний и приоритизируем контакты.": "Wir bilden einen Kundenstamm, bereinigen ihn von irrelevanten Unternehmen und priorisieren Kontakte.",
      "Холодный поиск клиентов": "Kalte Prospektion",
      "Цель работы — передача вашей команде компаний, готовых к предметному разговору, а не количество контактов.": "Ziel der Arbeit ist es, Ihrem Team Unternehmen zur Verfügung zu stellen, die zu einem inhaltlichen Gespräch bereit sind, und nicht die Anzahl der Kontakte.",
