      "языков продаж": "Verkaufssprachen",
      "AXCEND выстраивает полный цикл B2B-продаж: находим потенциальных клиентов, выходим на профильных руководителей, ведём переговоры, фиксируем результат в CRM и передаём готовых к сделке клиентов.": "AXCEND baut einen vollständigen B2B-Verkaufszyklus auf: Wir finden potenzielle Kunden, kontaktieren relevante Manager, verhandeln, erfassen die Ergebnisse im CRM und übertragen geschäftsbereite Kunden.",
      "AXCEND передаёт не просто контакты, а компании, которые поняли предложение, проявили интерес и согласились обсудить его с командой заказчика.": "AXCEND vermittelt nicht nur Kontakte, sondern auch Unternehmen, die das Angebot verstanden, Interesse gezeigt und sich bereit erklärt haben, es mit dem Team des Kunden zu besprechen.",
