      "Выходим на закупщиков и ЛПР": "Ci rivolgiamo agli acquirenti e ai decisori",
      "Выходим на клиентов, объясняем предложение, фиксируем реакцию, возражения и уровень заинтересованности.": "Contattiamo i clienti, spieghiamo la proposta, registriamo reazioni, obiezioni e livello di interesse.",
