      "Готовы обсуждать предметно": "Pronto per discutere in dettaglio",
      "Готовые сценарии под вашу задачу": "Script già pronti per il tuo compito",
      "Гранд Сити": "Grande città",
      "Грузия": "Georgia",
      "Да, проект можно запустить под конкретную нишу или конкретный продукт без расширения охвата.": "Sì, un progetto può essere lanciato per una nicchia specifica o un prodotto specifico senza ampliarne la portata.",
      "Да. Все контакты, статусы, заметки и записи переговоров остаются у заказчика.": "SÌ. Tutti i contatti, gli stati, le note e le registrazioni delle conversazioni rimangono presso il cliente.",
