      "Назначаем встречу с вашей командой и передаём контекст: кто клиент, в чём интерес, какие вопросы возникли.": "Organizziamo un incontro con il tuo team e illustriamo il contesto: chi è il cliente, qual è l'interesse, quali domande sono sorte.",
      "Мы продаём смыслами: разбираемся в продукте, ведём содержательный разговор с ЛПР и доводим до встречи, а не до отметки в отчёте.": "Vendiamo con significato: comprendiamo il prodotto, abbiamo una conversazione significativa con il decisore e lo portiamo a una riunione, e non a un segno nel rapporto.",
