      "новый рынок": "nuovo mercato",
      "Наши менеджеры не работают по шаблону. В этом одно из ключевых отличий AXCEND. Благодаря опыту в консалтинге и B2B продажах наши менеджеры понимают как устроен рынок, разбираются даже в сложных продуктах, четко понимая интересы бизнеса, постепенно доводя контакт до готовности к встрече с заказчиком.": "I nostri manager non lavorano secondo un modello. Questa è una delle differenze chiave tra AXCEND. Grazie all'esperienza nella consulenza e nelle vendite B2B, i nostri manager capiscono come funziona il mercato, comprendono prodotti anche complessi, comprendono chiaramente gli interessi dell'azienda, portando gradualmente il contatto alla disponibilità per un incontro con il cliente.",
      "Нужна база с вероятностью интереса, а не просто список": "Abbiamo bisogno di un database con una probabilità di interesse, non solo di un elenco",
      "НОВЫЙ РЫНОК": "NUOVO MERCATO",
      "ОАЭ": "Emirati Arabi Uniti",
      "Нужны новые B2B-клиенты, но нет сильной команды продаж": "Hai bisogno di nuovi clienti B2B, ma manca un forte team di vendita",
      "Нужны встречи с клиентами, а не отчёт о звонках": "Abbiamo bisogno di incontri con i clienti, non di rapporti sulle chiamate",
