      "Оценка ориентировочная. Точная модель строится после диагностики продукта и сегмента.": "La stima è indicativa. Un modello accurato viene costruito dopo aver diagnosticato il prodotto e il segmento.",
      "Перед стартом продаж изучаем рынок, конкурентов и целевую аудиторию. Смотрим, какие компании нуждаются в данном продукте, как сейчас продают аналогичные решения и какие аргументы сильнее всего работают в переговорах.": "Prima di iniziare le vendite, studiamo il mercato, i concorrenti e il pubblico target. Analizziamo quali aziende hanno bisogno di questo prodotto, come stanno attualmente vendendo soluzioni simili e quali argomenti funzionano più fortemente nelle negoziazioni.",
