      "Перед контактом с рынком нужно понять продукт, экономику сделки, аргументы для руководителей и возможные возражения.": "Prima di contattare il mercato è necessario comprendere il prodotto, l'economia della transazione, le argomentazioni per i manager e le possibili obiezioni.",
      "Передаётся информация: кто заинтересовался, в чём причина интереса, какие вопросы возникли, какие возражения были озвучены и что важно учесть на встрече.": "Vengono trasmesse informazioni: chi è interessato, qual è il motivo dell'interesse, quali domande sono sorte, quali obiezioni sono state espresse e cosa è importante tenere in considerazione durante la riunione.",
