      "ШАГ 04 ИЗ 07": "PASSO 04 DI 07",
      "B2B-диалогов в месяц": "dialoghi B2B al mese",
      "AXCEND выстраивает полный цикл B2B-продаж: находим потенциальных клиентов, выходим на профильных руководителей, ведём переговоры, фиксируем результат в CRM и передаём готовых к сделке клиентов.": "AXCEND costruisce un ciclo completo di vendite B2B: troviamo potenziali clienti, contattiamo i manager interessati, negoziamo, registriamo i risultati nel CRM e trasferiamo i clienti pronti per un accordo.",
      "AXCEND передаёт не просто контакты, а компании, которые поняли предложение, проявили интерес и согласились обсудить его с командой заказчика.": "AXCEND trasferisce non solo contatti, ma aziende che hanno compreso la proposta, hanno mostrato interesse e hanno accettato di discuterne con il team del cliente.",
      "AXCEND": "AXCEND",
      "B2B": "B2B",
      "CRM": "CRM",
      "FAQ": "FAQ",
      "WIN-BACK": "WIN-BACK",
      "win-back": "win-back",
      "ART-IDEI": "ART-IDEI",
