      "ГАРАНТИЯ": "GARANTIZAR",
      "Выходим на клиентов, объясняем предложение, фиксируем реакцию, возражения и уровень заинтересованности.": "Contactamos con los clientes, explicamos la propuesta, registramos reacciones, objeciones y nivel de interés.",
