      "Вы не хотите нанимать, обучать и контролировать менеджеров ради проверки нового направления.": "No desea contratar, capacitar y supervisar gerentes para probar una nueva dirección.",
      "Грузия": "Georgia",
      "Да. Все контакты, статусы, заметки и записи переговоров остаются у заказчика.": "Sí. Todos los contactos, estados, notas y grabaciones de conversaciones permanecen en poder del cliente.",
