      "Дожимаем тёплых до сделки": "Presionamos los tibios hasta el trato.",
      "ЖК «Левитан»": "Complejo residencial \"Levitan\"",
      "Дошли до содержательного разговора": "Hemos llegado a una conversación significativa",
      "Доводим до подписанного договора": "Llegamos a un acuerdo firmado.",
      "Доводим до первой отгрузки": "Lo llevamos al primer envío.",
      "Доктор Хорошев": "Doctor Joroshev",
      "Доктор Андрей Баранов": "Dr. Andrey Baranov",
      "из": "de",
      "Заказчик видит, как рынок реагирует на продукт: какие аргументы работают, какие сегменты откликаются, что мешает интересу и где требуется усилить предложение.": "El cliente ve cómo reacciona el mercado ante el producto: qué argumentos funcionan, qué segmentos responden, qué obstaculiza el interés y dónde es necesario reforzar la oferta.",
      "За счёт глубокого понимания продукта и точного подбора аудитории часть проектов даёт конверсию до 25–30% из целевых контактов во встречу.": "Gracias a un profundo conocimiento del producto y a una selección precisa de la audiencia, algunos proyectos logran una conversión de hasta un 25-30% de contactos objetivo a reuniones.",
      "Заказчик получает не только контакты, но и понимание, какие сегменты рынка реагируют лучше, где интерес выше, а где предложение вызывает слабую реакцию.": "El cliente no sólo recibe contactos, sino también una comprensión de qué segmentos del mercado responden mejor, dónde hay mayor interés y dónde la oferta provoca una reacción débil.",
      "исходящие": "extrovertido",
      "ИСХОДЯЩИЕ": "BANDEJA DE SALIDA",
      "Заранее зафиксированные критерии релевантности компании, подтверждённого интереса и засчитываемой встречи.": "Criterios prefijados de relevancia de la empresa, interés confirmado y reunión contable.",
      "Казахстан": "Kazajstán",
      "Закрываем входящие заявки": "Cerrar solicitudes entrantes",
      "Инкор Медицинские Сертификаты": "Certificados Médicos Incor",
      "Закрываем пилотные сделки": "Cerramos acuerdos piloto",
      "Как клиенты движутся по воронке": "Cómo se mueven los clientes a través del embudo",
      "Используем профессиональные системы анализа рынка и цифрового поведения компаний. Отслеживаем активность бизнеса, изменения внутри компаний, закупочные сигналы, рост направлений, интерес к определённым решениям и другие признаки спроса. Так нам удается найти только те компании, для которых предложение действительно актуально.": "Utilizamos sistemas profesionales para analizar el mercado y el comportamiento digital de las empresas. Seguimos la actividad empresarial, los cambios dentro de las empresas, las señales de compra, el crecimiento de áreas, el interés en determinadas soluciones y otras señales de demanda. De esta forma conseguimos encontrar sólo aquellas empresas para las que la oferta es realmente relevante.",
      "Как строится работа": "Cómo está estructurado el trabajo.",
      "Калькулятор": "Calculadora",
      "Ищем компании, которым продукт действительно может быть нужен — не «по списку», а по релевантности и рыночным сигналам.": "Buscamos empresas que realmente puedan necesitar el producto, no \"por lista\", sino por relevancia y señales del mercado.",
      "Катарсис": "Catarsis",
      "Кейсы": "Casos de éxito",
      "Калькулятор результата": "Calculadora de resultados",
      "КАЛЬКУЛЯТОР РЕЗУЛЬТАТА": "CALCULADORA DE RESULTADOS",
      "Каскад строительство": "Construcción en cascada",
      "Квалифицируем и отсекаем нецелевых": "Calificamos y cortamos no dirigidos.",
      "Казахстан, Узбекистан, Южная Корея, Турция, Армения, Кыргызстан и сопредельные рынки СНГ.": "Kazajstán, Uzbekistán, Corea del Sur, Türkiye, Armenia, Kirguistán y los mercados vecinos de la CEI.",
      "Качественные контакты": "contactos de calidad",
