      "Цена продаваемого продукта/услуги, $": "Precio del producto/servicio vendido, $",
      "У нас входящие сыплются, а отвечать некому. Плюс по холодке надо звонить — а сил на это нет. Заберите всё, верните уже закрытые сделки.": "Nuestras bandejas de entrada se están inundando, pero no hay nadie que responda. Además, tienes que llamar cuando hace frío, pero no tienes fuerzas para hacerlo. Toma todo, devuelve las transacciones ya cerradas.",
      "Частые вопросы": "Preguntas frecuentes",
      "Фиксируем обязательства письменно: клиент заранее понимает, какой результат должен быть достигнут.": "Fijamos las obligaciones por escrito: el cliente comprende de antemano qué resultado debe lograrse.",
      "Что вы получаете": "¿Qué obtienes?",
      "Цель работы — передача вашей команде компаний, готовых к предметному разговору, а не количество контактов.": "El objetivo del trabajo es proporcionar a su equipo empresas listas para una conversación sustantiva, y no la cantidad de contactos.",
      "Формируем базу клиентов, очищаем её от нерелевантных компаний и приоритизируем контакты.": "Formamos una base de clientes, la limpiamos de empresas irrelevantes y priorizamos los contactos.",
