      "Юлия Смирнова «Ставки на себя»": "Yulia Smirnova “Apuesta por ti misma”",
      "AXCEND передаёт не просто контакты, а компании, которые поняли предложение, проявили интерес и согласились обсудить его с командой заказчика.": "AXCEND transfiere no sólo contactos, sino empresas que entendieron la propuesta, mostraron interés y aceptaron discutirla con el equipo del cliente.",
      "AXCEND выстраивает полный цикл B2B-продаж: находим потенциальных клиентов, выходим на профильных руководителей, ведём переговоры, фиксируем результат в CRM и передаём готовых к сделке клиентов.": "AXCEND construye un ciclo completo de ventas B2B: encontramos clientes potenciales, contactamos a los gerentes relevantes, negociamos, registramos los resultados en CRM y transferimos clientes que están listos para un trato.",
