      "Агентство «Мизель»": "«Мизел» агенттігі",
      "Азербайджан": "Әзірбайжан",
      "Анна Бушева": "Анна Бушева",
      "База целевых компаний": "Мақсатты компаниялардың мәліметтер базасы",
      "Армения": "Армения",
