      "Казахстан, Узбекистан, Южная Корея, Турция, Армения, Кыргызстан и сопредельные рынки СНГ.": "Қазақстан, Өзбекстан, Оңтүстік Корея, Түркия, Армения, Қырғызстан және көршілес ТМД нарықтары.",
