      "Кейсы": "Кейстер",
      "Команда заказчика не тратит время на поиск, первичные контакты, проверку интереса и отсев нерелевантных компаний — она подключается уже на стадии предметного разговора.": "Тапсырыс берушінің командасы іздеуге, бастапқы байланыстарға, қызығушылықты тексеруге және маңызды емес компанияларды тексеруге уақытты жоғалтпайды - ол маңызды әңгіме сатысында қатысады.",
