      "Мы продаём смыслами: разбираемся в продукте, ведём содержательный разговор с ЛПР и доводим до встречи, а не до отметки в отчёте.": "Мағынасы бар сатамыз: өнімді түсінеміз, шешім қабылдаушымен мағыналы әңгімелесеміз және оны есептегі белгіге емес, жиналысқа әкелеміз.",
