      "Перед контактом с рынком нужно понять продукт, экономику сделки, аргументы для руководителей и возможные возражения.": "Нарықпен байланыспас бұрын, сіз өнімді, транзакцияның экономикасын, менеджерлерге арналған дәлелдерді және ықтимал қарсылықтарды түсінуіңіз керек.",
      "Передаётся информация: кто заинтересовался, в чём причина интереса, какие вопросы возникли, какие возражения были озвучены и что важно учесть на встрече.": "Ақпарат беріледі: кім қызығушылық танытады, қызығушылықтың себебі неде, қандай сұрақтар туындады, қандай қарсылықтар айтылды және жиналыста нені ескеру маңызды.",
      "Передаём встречи и горячие лиды": "Біз кездесулер мен ыстық жетекшілерді ауыстырамыз",
