      "У нас входящие сыплются, а отвечать некому. Плюс по холодке надо звонить — а сил на это нет. Заберите всё, верните уже закрытые сделки.": "Кіріс жәшіктеріміз толып жатыр, бірақ жауап беретін ешкім жоқ. Сонымен қатар, сіз суық кезде қоңырау шалуыңыз керек, бірақ оны жасауға күшіңіз жетпейді. Барлығын алыңыз, жабық транзакцияларды қайтарыңыз.",
