      "B2B-диалогов в месяц": "Айына B2B диалогтары",
      "языков продаж": "сату тілдері",
      "AXCEND передаёт не просто контакты, а компании, которые поняли предложение, проявили интерес и согласились обсудить его с командой заказчика.": "AXCEND тек контактілерді ғана емес, ұсынысты түсінген, қызығушылық танытқан және оны тұтынушы командасымен талқылауға келіскен компанияларды да жібереді.",
      "AXCEND выстраивает полный цикл B2B-продаж: находим потенциальных клиентов, выходим на профильных руководителей, ведём переговоры, фиксируем результат в CRM и передаём готовых к сделке клиентов.": "AXCEND B2B сатылымының толық циклін құрады: біз әлеуетті клиенттерді табамыз, тиісті менеджерлермен байланысамыз, келіссөздер жүргіземіз, нәтижелерді CRM жүйесіне жазамыз және мәмілеге дайын клиенттерді тасымалдаймыз.",
