      "Вы не хотите нанимать, обучать и контролировать менеджеров ради проверки нового направления.": "Siz yangi yo'nalishni sinab ko'rish uchun menejerlarni yollashni, o'qitishni va nazorat qilishni xohlamaysiz.",
      "ВХОДЯЩИЕ": "INBOX",
      "Выходим на закупщиков и ЛПР": "Biz xaridorlar va qaror qabul qiluvchilarga murojaat qilamiz",
      "Гарантия": "Kafolat",
      "Выходим на клиентов, объясняем предложение, фиксируем реакцию, возражения и уровень заинтересованности.": "Biz mijozlar bilan bog'lanamiz, taklifni tushuntiramiz, reaktsiyalar, e'tirozlar va qiziqish darajasini yozamiz.",
