      "Делаем допродажи по текущей базе": "Biz joriy baza asosida yuqori sotuvlar qilamiz",
      "Да, проект можно запустить под конкретную нишу или конкретный продукт без расширения охвата.": "Ha, loyihani o'z ko'lamini kengaytirmasdan, ma'lum bir joy yoki muayyan mahsulot uchun boshlash mumkin.",
      "ДИСТРИБУЦИЯ": "TARQATISH",
      "дистрибуция": "tarqatish",
      "До 25–30% во встречу": "Har bir uchrashuv uchun 25-30% gacha",
      "Доводим до первой отгрузки": "Biz uni birinchi jo'natishga keltiramiz",
      "Дожимаем тёплых до сделки": "Kelishuvga qadar iliqlarni bosamiz",
      "для рынка СНГ": "",
      "Доктор Андрей Баранов": "Doktor Andrey Baranov",
      "Доводим до подписанного договора": "Biz imzolangan kelishuvga erishamiz",
      "ЖК «Левитан»": "\"Levitan\" turar-joy majmuasi",
      "Дошли до содержательного разговора": "Biz mazmunli suhbatga erishdik",
      "Заказчик получает не только контакты, но и понимание, какие сегменты рынка реагируют лучше, где интерес выше, а где предложение вызывает слабую реакцию.": "Xaridor nafaqat aloqalarni, balki bozor segmentlarining qaysi biri yaxshiroq javob berishini, qayerda qiziqish yuqori ekanligini va taklif zaif reaktsiyaga sabab bo'lganligini tushunishni ham oladi.",
      "За счёт глубокого понимания продукта и точного подбора аудитории часть проектов даёт конверсию до 25–30% из целевых контактов во встречу.": "Mahsulotni chuqur tushunish va tinglovchilarni aniq tanlash tufayli ba'zi loyihalar maqsadli aloqalardan uchrashuvlarga 25-30% gacha konvertatsiya qilishga erishadi.",
      "Доктор Хорошев": "Doktor Xoroshev",
      "Закрываем входящие заявки": "Kiruvchi so'rovlarni yopish",
      "Заказчик видит, как рынок реагирует на продукт: какие аргументы работают, какие сегменты откликаются, что мешает интересу и где требуется усилить предложение.": "Xaridor bozorning mahsulotga qanday munosabatda bo'lishini ko'radi: qaysi argumentlar ishlaydi, qaysi segmentlar javob beradi, qiziqishga nima to'sqinlik qiladi va taklifni qayerda kuchaytirish kerak.",
      "Закрываем пилотные сделки": "Biz uchuvchi kelishuvlarni yopyapmiz",
      "Заранее зафиксированные критерии релевантности компании, подтверждённого интереса и засчитываемой встречи.": "Kompaniyaning dolzarbligi uchun oldindan belgilangan mezonlar, tasdiqlangan qiziqish va hisoblangan uchrashuv.",
      "из": "dan",
      "Инкор Медицинские Сертификаты": "Incor tibbiy sertifikatlari",
      "Используем профессиональные системы анализа рынка и цифрового поведения компаний. Отслеживаем активность бизнеса, изменения внутри компаний, закупочные сигналы, рост направлений, интерес к определённым решениям и другие признаки спроса. Так нам удается найти только те компании, для которых предложение действительно актуально.": "Biz kompaniyalarning bozor va raqamli xatti-harakatlarini tahlil qilish uchun professional tizimlardan foydalanamiz. Biz biznes faolligini, kompaniyalar ichidagi o'zgarishlarni, xarid signallarini, hududlardagi o'sishni, muayyan yechimlarga qiziqishni va boshqa talab belgilarini kuzatamiz. Shunday qilib, biz faqat taklif haqiqatan ham tegishli bo'lgan kompaniyalarni topishga muvaffaq bo'lamiz.",
      "исходящие": "chiquvchi",
      "ИСХОДЯЩИЕ": "KUTISH",
      "Ищем компании, которым продукт действительно может быть нужен — не «по списку», а по релевантности и рыночным сигналам.": "Biz haqiqatan ham mahsulotga muhtoj bo'lishi mumkin bo'lgan kompaniyalarni qidirmoqdamiz - \"ro'yxat bo'yicha\" emas, balki tegishlilik va bozor signallari bo'yicha.",
      "Казахстан": "Qozog'iston",
      "Как клиенты движутся по воронке": "Mijozlar huni orqali qanday o'tadi",
