      "Катарсис": "Katarsis",
      "Казахстан, Узбекистан, Южная Корея, Турция, Армения, Кыргызстан и сопредельные рынки СНГ.": "Qozog‘iston, O‘zbekiston, Janubiy Koreya, Turkiya, Armaniston, Qirg‘iziston va qo‘shni MDH bozorlari.",
