      "Сколько занимает запуск проекта?": "Loyihani ishga tushirish uchun qancha vaqt ketadi?",
      "Собираем логику разговора: почему клиенту стоит слушать, какие проблемы закрывает продукт, что предлагать дальше.": "Biz suhbatning mantig'ini to'playmiz: nima uchun mijoz tinglashi kerak, mahsulot qanday muammolarni hal qiladi, keyin nimani taklif qiladi.",
