      "У нас входящие сыплются, а отвечать некому. Плюс по холодке надо звонить — а сил на это нет. Заберите всё, верните уже закрытые сделки.": "Bizning pochta qutilarimiz suv bosdi, lekin javob beradigan hech kim yo'q. Bundan tashqari, siz sovuq bo'lganda qo'ng'iroq qilishingiz kerak - lekin bunga kuchingiz yo'q. Hamma narsani oling, allaqachon yopilgan tranzaktsiyalarni qaytaring.",
      "Согласовываем критерии: отрасли, регионы, размер бизнеса, должности, признаки потребности.": "Biz mezonlar bo'yicha kelishib oldik: tarmoqlar, hududlar, biznes hajmi, pozitsiyalari, ehtiyoj belgilari.",
      "Узбекистан": "O'zbekiston",
