      "Средняя конверсия": "O'rtacha konvertatsiya",
      "Турция": "Turkiya",
      "Фиксируем обязательства письменно: клиент заранее понимает, какой результат должен быть достигнут.": "Biz majburiyatlarni yozma ravishda tuzatamiz: mijoz qanday natijaga erishish kerakligini oldindan tushunadi.",
      "Формируем базу клиентов, очищаем её от нерелевантных компаний и приоритизируем контакты.": "Biz mijozlar bazasini shakllantiramiz, uni ahamiyatsiz kompaniyalardan tozalaymiz va aloqalarga ustuvor ahamiyat beramiz.",
      "Финансы": "Moliya",
