      "Шаг": "Qadam",
      "Цель работы — передача вашей команде компаний, готовых к предметному разговору, а не количество контактов.": "Ishning maqsadi sizning jamoangizni aloqalar sonini emas, balki mazmunli suhbatga tayyor bo'lgan kompaniyalar bilan ta'minlashdir.",
