      "Юлия Смирнова «Ставки на себя»": "Yuliya Smirnova \"O'zingizga tikish\"",
      "языков продаж": "savdo tillari",
      "AXCEND выстраивает полный цикл B2B-продаж: находим потенциальных клиентов, выходим на профильных руководителей, ведём переговоры, фиксируем результат в CRM и передаём готовых к сделке клиентов.": "AXCEND B2B savdosining to‘liq tsiklini quradi: biz potentsial mijozlarni topamiz, tegishli menejerlar bilan bog‘lanamiz, muzokaralar olib boramiz, natijalarni CRM-ga yozamiz va kelishuvga tayyor bo‘lgan mijozlarni o‘tkazamiz.",
      "AXCEND передаёт не просто контакты, а компании, которые поняли предложение, проявили интерес и согласились обсудить его с командой заказчика.": "AXCEND nafaqat aloqalarni, balki taklifni tushungan, qiziqish bildirgan va uni mijoz jamoasi bilan muhokama qilishga rozi bo'lgan kompaniyalarni o'tkazadi.",
      "B2B-диалогов в месяц": "Oyiga B2B dialoglari",
