      "Выходим на клиентов, объясняем предложение, фиксируем реакцию, возражения и уровень заинтересованности.": "Биз кардарлар менен байланышабыз, сунушту түшүндүрөбүз, реакцияларды, каршылыктарды жана кызыгуунун деңгээлин жазабыз.",
