      "Да, проект можно запустить под конкретную нишу или конкретный продукт без расширения охвата.": "Ооба, долбоордун масштабын кеңейтпестен эле белгилүү бир орунга же белгилүү бир продуктуга карата ишке киргизсе болот.",
