      "Заранее зафиксированные критерии релевантности компании, подтверждённого интереса и засчитываемой встречи.": "Компаниянын актуалдуулугунун алдын ала белгиленген критерийлери, тастыкталган пайыздар жана эсептелүүчү жолугушуу.",
      "Закрываем пилотные сделки": "Биз пилоттук келишимдерди жаап жатабыз",
