      "Наши менеджеры не работают по шаблону. В этом одно из ключевых отличий AXCEND. Благодаря опыту в консалтинге и B2B продажах наши менеджеры понимают как устроен рынок, разбираются даже в сложных продуктах, четко понимая интересы бизнеса, постепенно доводя контакт до готовности к встрече с заказчиком.": "Биздин жетекчилер шаблон боюнча иштешпейт. Бул AXCEND ортосундагы негизги айырмачылыктардын бири болуп саналат. Консалтинг жана B2B сатуу боюнча тажрыйбанын аркасында биздин менеджерлер рыноктун кантип иштээрин түшүнүшөт, ал тургай татаал продуктыларды түшүнүшөт, бизнестин кызыкчылыктарын так түшүнүшөт, акырындык менен байланышты кардар менен жолугушууга даярдоого чейин жеткиришет.",
