      "Формируем базу клиентов, очищаем её от нерелевантных компаний и приоритизируем контакты.": "Биз кардар базасын түзүп, аны тиешеси жок компаниялардан тазалап, байланыштарга артыкчылык беребиз.",
      "У нас входящие сыплются, а отвечать некому. Плюс по холодке надо звонить — а сил на это нет. Заберите всё, верните уже закрытые сделки.": "Биздин почталарыбызга толуп жатат, бирок жооп бере турган эч ким жок. Мындан тышкары, сиз суук болгондо чалышыңыз керек - бирок ага күчүңүз жетпейт. Баарын алыңыз, буга чейин жабылган транзакцияларды кайтарыңыз.",
      "Фиксируем обязательства письменно: клиент заранее понимает, какой результат должен быть достигнут.": "Биз милдеттенмелерди жазуу жүзүндө бекитебиз: кардар кандай натыйжага жетишүү керектигин алдын ала түшүнөт.",
