      "Чем отличаетесь от классического колл-центра?": "Классикалык байланыш борборунан эмнеси менен айырмаланат?",
      "Цель работы — передача вашей команде компаний, готовых к предметному разговору, а не количество контактов.": "Иштин максаты - сиздин командаңызды байланыштардын санын эмес, олуттуу сүйлөшүүгө даяр компаниялар менен камсыз кылуу.",
