      "ШАГ 07 ИЗ 07": "07-КАДАМ",
      "ШАГ 06 ИЗ 07": "06-КАДАМ 07",
      "Эбру": "Эбру",
      "Юлия Смирнова «Ставки на себя»": "Юлия Смирнова \"Өзүңө коюм\"",
      "языков продаж": "сатуу тилдери",
      "B2B-диалогов в месяц": "Айына B2B диалогдору",
      "AXCEND выстраивает полный цикл B2B-продаж: находим потенциальных клиентов, выходим на профильных руководителей, ведём переговоры, фиксируем результат в CRM и передаём готовых к сделке клиентов.": "AXCEND B2B сатуунун толук циклин курат: биз потенциалдуу кардарларды табабыз, тиешелүү менеджерлер менен байланышабыз, сүйлөшүүлөрдү жүргүзөбүз, натыйжаларды CRMге жаздырабыз жана келишимге даяр кардарларды өткөрүп беребиз.",
      "AXCEND передаёт не просто контакты, а компании, которые поняли предложение, проявили интерес и согласились обсудить его с командой заказчика.": "AXCEND жөн гана байланыштарды эмес, сунушту түшүнгөн, кызыгуу көрсөткөн жана аны кардардын командасы менен талкуулоого макул болгон компанияларды өткөрүп берет.",
      "AXCEND": "AXCEND",
