      "Выходим на закупщиков и ЛПР": "Մենք դիմում ենք գնորդներին և որոշում կայացնողներին",
      "Гарантия в договоре": "Երաշխիք պայմանագրում",
      "Грузия": "Վրաստան",
      "ГАРАНТИЯ": "ԵՐԱՇԽԻՔ",
      "Гарантия от 5% закрепляется в договоре": "Պայմանագրում ամրագրված է 5% երաշխիք",
      "Готовые сценарии под вашу задачу": "Պատրաստի սցենարներ ձեր առաջադրանքի համար",
      "Готовы обсуждать предметно": "Պատրաստ է մանրամասն քննարկել",
      "Да. Все контакты, статусы, заметки и записи переговоров остаются у заказчика.": "Այո՛։ Բոլոր կոնտակտները, կարգավիճակները, գրառումները և խոսակցությունների ձայնագրությունները մնում են հաճախորդի մոտ:",
      "Да, проект можно запустить под конкретную нишу или конкретный продукт без расширения охвата.": "Այո, նախագիծը կարող է գործարկվել կոնկրետ խորշի կամ կոնկրետ արտադրանքի համար՝ առանց դրա շրջանակը ընդլայնելու:",
      "Гранд Сити": "Գրանդ Սիթի",
