      "Диагностика продукта": "Ապրանքի ախտորոշում",
      "для рынка СНГ": "",
      "диалогов": "երկխոսություններ",
      "ДИСТРИБУЦИЯ": "ՏԱՐԱԾՈՒՄ",
      "Доводим до первой отгрузки": "Մենք բերում ենք այն առաջին առաքմանը",
      "Дожимаем тёплых до сделки": "Տաքերը սեղմում ենք մինչև գործարքը",
      "Делаем допродажи по текущей базе": "Մենք գնումներ ենք կատարում ընթացիկ բազայի հիման վրա",
      "До 25–30% во встречу": "Մինչև 25–30% մեկ հանդիպման համար",
      "Дипломат (мужская одежда)": "Դիվանագետ (տղամարդկանց հագուստ)",
      "Доводим до подписанного договора": "Մենք բերում ենք ստորագրված համաձայնագրի",
      "Доктор Андрей Баранов": "Բժիշկ Անդրեյ Բարանով",
      "Доктор Хорошев": "Բժիշկ Խորոշև",
      "ЖК «Левитан»": "«Լևիտան» բնակելի համալիր",
      "Дошли до содержательного разговора": "Մենք հասանք բովանդակալից խոսակցության",
      "Заказчик видит, как рынок реагирует на продукт: какие аргументы работают, какие сегменты откликаются, что мешает интересу и где требуется усилить предложение.": "Հաճախորդը տեսնում է, թե ինչպես է շուկան արձագանքում ապրանքին. որ փաստարկներն են աշխատում, որ հատվածներն են արձագանքում, ինչը խանգարում է հետաքրքրությանը և որտեղ է առաջարկը պետք ամրապնդվի:",
      "Закрываем пилотные сделки": "Մենք փակում ենք փորձնական գործարքները",
      "из": "-ից",
      "Заранее зафиксированные критерии релевантности компании, подтверждённого интереса и засчитываемой встречи.": "Ընկերության համապատասխանության, հաստատված հետաքրքրության և հաշվելի հանդիպման համար նախապես ամրագրված չափանիշներ:",
      "Закрываем входящие заявки": "Մուտքային հարցումների փակում",
      "За счёт глубокого понимания продукта и точного подбора аудитории часть проектов даёт конверсию до 25–30% из целевых контактов во встречу.": "Արտադրանքի խորը ըմբռնման և լսարանի ճշգրիտ ընտրության շնորհիվ որոշ նախագծեր հասնում են մինչև 25–30% փոխակերպման՝ թիրախային կոնտակտներից հանդիպումների:",
      "Заказчик получает не только контакты, но и понимание, какие сегменты рынка реагируют лучше, где интерес выше, а где предложение вызывает слабую реакцию.": "Հաճախորդը ստանում է ոչ միայն կոնտակտներ, այլև հասկացողություն, թե շուկայի որ հատվածներն են ավելի լավ արձագանքում, որտեղ հետաքրքրությունն ավելի մեծ է, և որտեղ առաջարկը թույլ արձագանք է առաջացնում:",
      "Инкор Медицинские Сертификаты": "Incor բժշկական վկայականներ",
      "ИСХОДЯЩИЕ": "ԵԼՔԱՅԻՆ ԲՈՔՍ",
      "исходящие": "արտագնա",
      "Ищем компании, которым продукт действительно может быть нужен — не «по списку», а по релевантности и рыночным сигналам.": "Մենք փնտրում ենք ընկերություններ, որոնք իրականում կարող են ապրանքի կարիք ունենալ՝ ոչ «ըստ ցանկի», այլ ըստ համապատասխանության և շուկայական ազդանշանների:",
      "Используем профессиональные системы анализа рынка и цифрового поведения компаний. Отслеживаем активность бизнеса, изменения внутри компаний, закупочные сигналы, рост направлений, интерес к определённым решениям и другие признаки спроса. Так нам удается найти только те компании, для которых предложение действительно актуально.": "Մենք օգտագործում ենք պրոֆեսիոնալ համակարգեր ընկերությունների շուկայի և թվային վարքագծի վերլուծության համար: Մենք վերահսկում ենք բիզնեսի ակտիվությունը, ընկերությունների ներսում փոփոխությունները, գնումների ազդանշանները, ոլորտների աճը, որոշակի լուծումների նկատմամբ հետաքրքրությունը և պահանջարկի այլ նշաններ: Այս կերպ մեզ հաջողվում է գտնել միայն այն ընկերությունները, որոնց համար առաջարկն իսկապես տեղին է:",
      "Казахстан, Узбекистан, Южная Корея, Турция, Армения, Кыргызстан и сопредельные рынки СНГ.": "Ղազախստան, Ուզբեկստան, Հարավային Կորեա, Թուրքիա, Հայաստան, Ղրղզստան և հարևան ԱՊՀ շուկաներ։",
      "КАЛЬКУЛЯТОР РЕЗУЛЬТАТА": "ԱՐԴՅՈՒՆՔՆԵՐԻ ՀԱՇՎԻՉ",
      "Каскад строительство": "Կասկադի կառուցում",
      "Как клиенты движутся по воронке": "Ինչպես են հաճախորդները շարժվում ձագարով",
      "Казахстан": "Ղազախստան",
