      "Цель работы — передача вашей команде компаний, готовых к предметному разговору, а не количество контактов.": "Աշխատանքի նպատակն է ձեր թիմին տրամադրել բովանդակային զրույցի պատրաստ ընկերություններ, այլ ոչ թե կոնտակտների քանակ:",
