      "Фиксируем обязательства письменно: клиент заранее понимает, какой результат должен быть достигнут.": "Մենք պարտավորությունները ամրագրում ենք գրավոր. հաճախորդը նախապես հասկանում է, թե ինչ արդյունքի պետք է հասնել:",
