      "Юлия Смирнова «Ставки на себя»": "Յուլիա Սմիրնովա «Գրազ դիր քեզ վրա»",
      "B2B-диалогов в месяц": "B2B երկխոսություններ ամսական",
      "AXCEND выстраивает полный цикл B2B-продаж: находим потенциальных клиентов, выходим на профильных руководителей, ведём переговоры, фиксируем результат в CRM и передаём готовых к сделке клиентов.": "AXCEND-ը կառուցում է B2B վաճառքի ամբողջական ցիկլ. մենք գտնում ենք պոտենցիալ հաճախորդների, կապվում ենք համապատասխան մենեջերների հետ, բանակցում, գրանցում արդյունքները CRM-ում և փոխանցում հաճախորդներին, ովքեր պատրաստ են գործարքի:",
      "AXCEND передаёт не просто контакты, а компании, которые поняли предложение, проявили интерес и согласились обсудить его с командой заказчика.": "AXCEND-ը փոխանցում է ոչ միայն կոնտակտներ, այլ ընկերություններ, որոնք հասկացել են առաջարկը, հետաքրքրություն են ցուցաբերել և համաձայնել քննարկել այն հաճախորդի թիմի հետ:",
      "AXCEND": "AXCEND",
      "B2B": "B2B",
      "CRM": "CRM",
