      "Внешний отдел B2B‑продаж": "გარე B2B გაყიდვების განყოფილება",
      "Возвращаем в активные сделки": "დაუბრუნდით აქტიურ ტრანზაქციებს",
      "Ведём холодный поиск и прозвон": "ვატარებთ ცივ ძებნას და ვურეკავთ",
