      "ВХОДЯЩИЕ": "INBOX",
      "Вы не хотите нанимать, обучать и контролировать менеджеров ради проверки нового направления.": "თქვენ არ გსურთ დაიქირაოთ, მოამზადოთ და აკონტროლოთ მენეჯერები ახალი მიმართულების შესამოწმებლად.",
      "Воронка продаж": "გაყიდვების ძაბრი",
      "ВОРОНКА ПРОДАЖ": "გაყიდვების ძაბრი",
      "Выходим на клиентов, объясняем предложение, фиксируем реакцию, возражения и уровень заинтересованности.": "ჩვენ ვუკავშირდებით კლიენტებს, ვუხსნით წინადადებას, ვაფიქსირებთ რეაქციებს, წინააღმდეგობებს და ინტერესის დონეს.",
      "ГАРАНТИЯ": "გარანტია",
      "Грузия": "საქართველოს",
      "Выходим на закупщиков и ЛПР": "ჩვენ მივმართავთ მყიდველებს და გადაწყვეტილების მიმღებებს",
      "Гарантия в договоре": "გარანტია ხელშეკრულებაში",
      "Готовые сценарии под вашу задачу": "მზა სკრიპტები თქვენი ამოცანისთვის",
      "Гарантия от 5% закрепляется в договоре": "ხელშეკრულებაში 5%-იანი გარანტიაა დაფიქსირებული",
      "Готовы обсуждать предметно": "მზადაა დეტალურად განიხილოს",
      "Гранд Сити": "დიდი ქალაქი",
      "Дальше →": "განაგრძეთ →",
      "дистрибуция": "განაწილება",
      "Диагностика продукта": "პროდუქტის დიაგნოსტიკა",
      "диалогов": "დიალოგები",
      "Да, проект можно запустить под конкретную нишу или конкретный продукт без расширения охвата.": "დიახ, პროექტის გაშვება შესაძლებელია კონკრეტული ნიშისთვის ან კონკრეტული პროდუქტისთვის მისი ფარგლების გაფართოების გარეშე.",
      "для рынка СНГ": "",
      "ДИСТРИБУЦИЯ": "დისტრიბუცია",
      "Да. Все контакты, статусы, заметки и записи переговоров остаются у заказчика.": "დიახ. ყველა კონტაქტი, სტატუსი, ჩანაწერი და საუბრების ჩანაწერი რჩება მომხმარებელს.",
      "До 25–30% во встречу": "25-30%-მდე თითო შეხვედრაზე",
      "Доводим до первой отгрузки": "ჩვენ მივყავართ პირველ გადაზიდვაზე",
      "Доводим до подписанного договора": "მივაღწევთ ხელმოწერილ ხელშეკრულებას",
      "Делаем допродажи по текущей базе": "ჩვენ ვაწარმოებთ გაყიდვებს მიმდინარე ბაზის საფუძველზე",
      "Дипломат (мужская одежда)": "დიპლომატი (მამაკაცის ტანსაცმელი)",
      "Доктор Хорошев": "ექიმი ხოროშევი",
      "Заказчик получает не только контакты, но и понимание, какие сегменты рынка реагируют лучше, где интерес выше, а где предложение вызывает слабую реакцию.": "მომხმარებელი იღებს არა მხოლოდ კონტაქტებს, არამედ იმის გაგებას, თუ რომელი ბაზრის სეგმენტები რეაგირებენ უკეთესად, სად არის უფრო მაღალი ინტერესი და სად იწვევს შეთავაზება სუსტ რეაქციას.",
      "Заказчик видит, как рынок реагирует на продукт: какие аргументы работают, какие сегменты откликаются, что мешает интересу и где требуется усилить предложение.": "მომხმარებელი ხედავს, როგორ რეაგირებს ბაზარი პროდუქტზე: რომელი არგუმენტები მუშაობს, რომელი სეგმენტები პასუხობენ, რა აფერხებს ინტერესს და სად სჭირდება შეთავაზების გაძლიერება.",
      "За счёт глубокого понимания продукта и точного подбора аудитории часть проектов даёт конверсию до 25–30% из целевых контактов во встречу.": "პროდუქტის ღრმა გაგებისა და აუდიტორიის ზუსტი შერჩევის გამო, ზოგიერთი პროექტი აღწევს 25-30%-მდე კონვერტაციას სამიზნე კონტაქტებიდან შეხვედრებზე.",
      "Закрываем входящие заявки": "შემომავალი მოთხოვნების დახურვა",
      "Дошли до содержательного разговора": "ჩვენ მივაღწიეთ მნიშვნელოვან საუბარს",
      "ЖК «Левитан»": "საცხოვრებელი კომპლექსი \"ლევიტანი\"",
      "Дожимаем тёплых до сделки": "თბილებს ვაჭერთ გარიგებამდე",
      "Доктор Андрей Баранов": "დოქტორი ანდრეი ბარანოვი",
      "Закрываем пилотные сделки": "ჩვენ ვხურავთ საპილოტე გარიგებებს",
