      "Доктор Хорошев": "Doktor Xoroşev",
      "Заказчик получает не только контакты, но и понимание, какие сегменты рынка реагируют лучше, где интерес выше, а где предложение вызывает слабую реакцию.": "Müştəri yalnız əlaqələri deyil, həm də hansı bazar seqmentlərinin daha yaxşı cavab verdiyini, marağın harada daha yüksək olduğunu və təklifin zəif reaksiyaya səbəb olduğunu başa düşür.",
      "За счёт глубокого понимания продукта и точного подбора аудитории часть проектов даёт конверсию до 25–30% из целевых контактов во встречу.": "Məhsulu dərindən başa düşmək və auditoriyanın dəqiq seçimi sayəsində bəzi layihələr hədəf təmaslardan görüşlərə 25-30%-ə qədər keçid əldə edir.",
      "Заказчик видит, как рынок реагирует на продукт: какие аргументы работают, какие сегменты откликаются, что мешает интересу и где требуется усилить предложение.": "Müştəri bazarın məhsula necə reaksiya verdiyini görür: hansı arqumentlər işləyir, hansı seqmentlər cavab verir, marağa nə mane olur və təklifi harada gücləndirmək lazımdır.",
