      "Казахстан, Узбекистан, Южная Корея, Турция, Армения, Кыргызстан и сопредельные рынки СНГ.": "Qazaxıstan, Özbəkistan, Cənubi Koreya, Türkiyə, Ermənistan, Qırğızıstan və qonşu MDB bazarları.",
      "Ищем компании, которым продукт действительно может быть нужен — не «по списку», а по релевантности и рыночным сигналам.": "Biz həqiqətən məhsula ehtiyacı ola biləcək şirkətləri axtarırıq - \"siyahıya görə\" deyil, uyğunluq və bazar siqnallarına görə.",
      "Заранее зафиксированные критерии релевантности компании, подтверждённого интереса и засчитываемой встречи.": "Şirkət uyğunluğu, təsdiqlənmiş maraq və hesablana bilən görüş üçün əvvəlcədən müəyyən edilmiş meyarlar.",
      "Инкор Медицинские Сертификаты": "Incor Tibbi Sertifikatlar",
      "Как клиенты движутся по воронке": "Müştərilərin huni vasitəsilə necə hərəkət etməsi",
      "Как строится работа": "İş necə qurulur",
      "Используем профессиональные системы анализа рынка и цифрового поведения компаний. Отслеживаем активность бизнеса, изменения внутри компаний, закупочные сигналы, рост направлений, интерес к определённым решениям и другие признаки спроса. Так нам удается найти только те компании, для которых предложение действительно актуально.": "Biz şirkətlərin bazarını və rəqəmsal davranışını təhlil etmək üçün peşəkar sistemlərdən istifadə edirik. Biz biznes fəaliyyətini, şirkətlər daxilində dəyişiklikləri, satınalma siqnallarını, sahələrdə artımı, müəyyən həllərə marağı və digər tələb əlamətlərini izləyirik. Bu yolla biz yalnız təklifin həqiqətən aktual olduğu şirkətləri tapmağı bacarırıq.",
      "Кейсы": "Keislər",
