      "Мы продаём смыслами: разбираемся в продукте, ведём содержательный разговор с ЛПР и доводим до встречи, а не до отметки в отчёте.": "Mənası ilə satırıq: məhsulu başa düşürük, qərar verən şəxslə mənalı söhbət edirik və hesabatda işarəyə deyil, görüşə gətiririk.",
      "Назначаем встречу с вашей командой и передаём контекст: кто клиент, в чём интерес, какие вопросы возникли.": "Komandanızla görüş təşkil edirik və konteksti çatdırırıq: müştəri kimdir, maraq nədir, hansı suallar yaranıb.",
      "Находим дилеров, оптовиков, торговые дома": "Biz dilerlər, topdansatışçılar, ticarət evləri tapırıq",
      "Находим первых клиентов и партнёров": "Biz ilk müştərilərimizi və tərəfdaşlarımızı tapırıq",
      "Не случайный список компаний, а отобранная база организаций, которым продукт заказчика может быть релевантен по отрасли, размеру, географии, роли и признакам возможной потребности.": "Şirkətlərin təsadüfi siyahısı deyil, müştərinin məhsulunun sənaye, ölçü, coğrafiya, rol və mümkün ehtiyac əlamətlərinə görə uyğun ola biləcəyi təşkilatların seçilmiş məlumat bazası.",
      "Наши менеджеры не работают по шаблону. В этом одно из ключевых отличий AXCEND. Благодаря опыту в консалтинге и B2B продажах наши менеджеры понимают как устроен рынок, разбираются даже в сложных продуктах, четко понимая интересы бизнеса, постепенно доводя контакт до готовности к встрече с заказчиком.": "Menecerlərimiz şablon üzrə işləmir. Bu, AXCEND arasındakı əsas fərqlərdən biridir. Konsaltinq və B2B satış təcrübəsi sayəsində menecerlərimiz bazarın necə işlədiyini başa düşür, hətta mürəkkəb məhsulları başa düşür, biznesin maraqlarını aydın şəkildə başa düşür, təmasları tədricən müştəri ilə görüşə hazır vəziyyətə gətirir.",
