      "Оценка ориентировочная. Точная модель строится после диагностики продукта и сегмента.": "Qiymətləndirmə göstəricidir. Məhsulun və seqmentin diaqnostikasından sonra dəqiq model qurulur.",
      "Пакеты-сценарии": "Skript Paketləri",
      "ПАКЕТЫ-СЦЕНАРИИ": "Skript paketləri",
      "Передаётся информация: кто заинтересовался, в чём причина интереса, какие вопросы возникли, какие возражения были озвучены и что важно учесть на встрече.": "Məlumat ötürülür: kim maraqlanır, marağın səbəbi nədir, hansı suallar yaranıb, hansı etirazlar səsləndirilib və iclasda nələrin nəzərə alınması vacibdir.",
      "Перед контактом с рынком нужно понять продукт, экономику сделки, аргументы для руководителей и возможные возражения.": "Bazarla əlaqə qurmazdan əvvəl məhsulu, əməliyyatın iqtisadiyyatını, menecerlər üçün arqumentləri və mümkün etirazları başa düşməlisiniz.",
