      "Перед стартом продаж изучаем рынок, конкурентов и целевую аудиторию. Смотрим, какие компании нуждаются в данном продукте, как сейчас продают аналогичные решения и какие аргументы сильнее всего работают в переговорах.": "Satışa başlamazdan əvvəl bazarı, rəqibləri və hədəf auditoriyanı öyrənirik. Hansı şirkətlərin bu məhsula ehtiyac duyduğuna, hazırda oxşar həlləri necə satdıqlarına və danışıqlarda hansı arqumentlərin daha çox işlədiyinə baxırıq.",
      "Перезваниваем за 5 минут после заявки": "Müraciətdən sonra 5 dəqiqə ərzində sizə zəng edirik",
