      "Разбираемся в продукте, бизнес-модели и логике сделки до начала контакта с рынком.": "Biz bazarla əlaqə saxlamazdan əvvəl məhsulu, biznes modelini və əməliyyat məntiqini başa düşürük.",
      "Расскажите о продукте и целевом рынке — мы покажем, какой результат реалистично получить и как будет устроена работа.": "Məhsul və hədəf bazar haqqında bizə məlumat verin - biz sizə hansı real nəticələr əldə edə biləcəyinizi və işin necə qurulacağını göstərəcəyik.",
