      "Собираем логику разговора: почему клиенту стоит слушать, какие проблемы закрывает продукт, что предлагать дальше.": "Söhbətin məntiqini toplayırıq: müştəri niyə dinləməlidir, məhsul hansı problemləri həll edir, bundan sonra nə təklif etmək lazımdır.",
      "Согласовываем критерии: отрасли, регионы, размер бизнеса, должности, признаки потребности.": "Biz meyarlar üzrə razılaşırıq: sənayelər, regionlar, biznesin həcmi, mövqelər, ehtiyac əlamətləri.",
