      "У нас входящие сыплются, а отвечать некому. Плюс по холодке надо звонить — а сил на это нет. Заберите всё, верните уже закрытые сделки.": "İnboxlarımız su basır, amma cavab verən yoxdur. Üstəlik, soyuq olanda zəng etməlisən, amma buna gücün çatmır. Hər şeyi götür, artıq bağlanmış əməliyyatları qaytar.",
      "Частые вопросы": "Tez-tez verilən suallar",
