      "Чем отличаетесь от классического колл-центра?": "Klassik zəng mərkəzindən nə ilə fərqlənirsiniz?",
      "Фиксируем обязательства письменно: клиент заранее понимает, какой результат должен быть достигнут.": "Biz öhdəlikləri yazılı şəkildə müəyyənləşdiririk: müştəri hansı nəticəyə nail olmaq lazım olduğunu əvvəlcədən başa düşür.",
      "Формируем базу клиентов, очищаем её от нерелевантных компаний и приоритизируем контакты.": "Biz müştəri bazası formalaşdırırıq, onu aidiyyəti olmayan şirkətlərdən təmizləyirik və əlaqələri prioritetləşdiririk.",
      "Цель работы — передача вашей команде компаний, готовых к предметному разговору, а не количество контактов.": "İşin məqsədi komandanızı təmasların sayını deyil, məzmunlu söhbətə hazır şirkətlərlə təmin etməkdir.",
