      "B2B-диалогов в месяц": "Ayda B2B dialoqları",
      "языков продаж": "satış dilləri",
      "AXCEND передаёт не просто контакты, а компании, которые поняли предложение, проявили интерес и согласились обсудить его с командой заказчика.": "AXCEND yalnız əlaqələri deyil, təklifi başa düşən, maraq göstərən və müştəri komandası ilə müzakirə etməyə razı olan şirkətləri də köçürür.",
      "AXCEND выстраивает полный цикл B2B-продаж: находим потенциальных клиентов, выходим на профильных руководителей, ведём переговоры, фиксируем результат в CRM и передаём готовых к сделке клиентов.": "AXCEND B2B satışlarının tam dövrü qurur: biz potensial müştərilər tapırıq, müvafiq menecerlərlə əlaqə saxlayır, danışıqlar aparırıq, nəticələri CRM-də qeyd edirik və sövdələşməyə hazır olan müştəriləri köçürür.",
