      "Выходим на клиентов, объясняем предложение, фиксируем реакцию, возражения и уровень заинтересованности.": "نقوم بالاتصال بالعملاء وشرح الاقتراح وتسجيل ردود الفعل والاعتراضات ومستوى الاهتمام.",
      "диалогов": "الحوارات",
      "Да, проект можно запустить под конкретную нишу или конкретный продукт без расширения охвата.": "نعم يمكن إطلاق مشروع لقطاع معين أو منتج معين دون توسيع نطاقه.",
      "Да. Все контакты, статусы, заметки и записи переговоров остаются у заказчика.": "نعم. تبقى جميع جهات الاتصال والحالات والملاحظات وتسجيلات المحادثات مع العميل.",
