      "Назначаем встречу с вашей командой и передаём контекст: кто клиент, в чём интерес, какие вопросы возникли.": "نقوم بإعداد اجتماع مع فريقك وننقل السياق: من هو العميل، ما هي الفائدة، ما هي الأسئلة التي نشأت.",
