      "Нужны встречи с клиентами, а не отчёт о звонках": "نحن بحاجة إلى اجتماعات مع العملاء، وليس تقارير الاتصال",
      "ОАЭ": "الإمارات العربية المتحدة",
      "Наши менеджеры не работают по шаблону. В этом одно из ключевых отличий AXCEND. Благодаря опыту в консалтинге и B2B продажах наши менеджеры понимают как устроен рынок, разбираются даже в сложных продуктах, четко понимая интересы бизнеса, постепенно доводя контакт до готовности к встрече с заказчиком.": "مديرينا لا يعملون وفق قالب. وهذا أحد الاختلافات الرئيسية بين AXCEND. بفضل الخبرة في الاستشارات ومبيعات B2B، يفهم مديرونا كيفية عمل السوق، ويفهمون حتى المنتجات المعقدة، ويفهمون بوضوح اهتمامات العمل، مما يجعل الاتصال تدريجيًا جاهزًا للقاء العميل.",
      "Не случайный список компаний, а отобранная база организаций, которым продукт заказчика может быть релевантен по отрасли, размеру, географии, роли и признакам возможной потребности.": "ليست قائمة عشوائية بالشركات، بل قاعدة بيانات مختارة للمؤسسات التي قد يكون منتج العميل ذا صلة بها حسب الصناعة والحجم والجغرافيا والدور وعلامات الحاجة المحتملة.",
