      "УЛЦ «Качество»": "يو إل سي \"الجودة\"",
      "Частые вопросы": "الأسئلة المتداولة",
      "У нас входящие сыплются, а отвечать некому. Плюс по холодке надо звонить — а сил на это нет. Заберите всё, верните уже закрытые сделки.": "صناديق البريد الوارد لدينا تمتلئ، ولكن لا يوجد أحد للرد. بالإضافة إلى ذلك، يتعين عليك الاتصال عندما يكون الجو باردًا - لكن ليس لديك القوة للقيام بذلك. خذ كل شيء، وأعد المعاملات المغلقة بالفعل.",
      "Холодный поиск клиентов": "التنقيب البارد",
      "ФинМарина": "فينمارينا",
      "Что вы получаете": "ماذا تحصل",
      "Фиксируем обязательства письменно: клиент заранее понимает, какой результат должен быть достигнут.": "نقوم بإصلاح الالتزامات كتابيًا: يفهم العميل مسبقًا النتيجة التي يجب تحقيقها.",
      "Шаг": "خطوة",
