      "ЧТО ВЫ ПОЛУЧАЕТЕ": "ما الذي ستحصل عليه؟",
      "Что входит в гарантию?": "ما هو مدرج في الضمان؟",
      "Чем отличаетесь от классического колл-центра?": "كيف تختلف عن مركز الاتصال الكلاسيكي؟",
      "Что делаем": "ما الذي نقدمه",
      "ШАГ 01 ИЗ 07": "الخطوة 01 من 07",
      "Цель работы — передача вашей команде компаний, готовых к предметному разговору, а не количество контактов.": "الهدف من العمل هو تزويد فريقك بالشركات الجاهزة لإجراء محادثة موضوعية، وليس بعدد جهات الاتصال.",
      "Формируем базу клиентов, очищаем её от нерелевантных компаний и приоритизируем контакты.": "نحن نشكل قاعدة عملاء وننظفها من الشركات غير ذات الصلة ونعطي الأولوية للاتصالات.",
      "ШАГ 06 ИЗ 07": "الخطوة 06 من 07",
      "ШАГ 04 ИЗ 07": "الخطوة 04 من 07",
      "ШАГ 03 ИЗ 07": "الخطوة 03 من 07",
      "ШАГ 05 ИЗ 07": "الخطوة 05 من 07",
      "Эбру": "إبرو",
      "Энергетика": "طاقة",
      "Южная Корея": "كوريا الجنوبية",
      "Юлия Смирнова «Ставки на себя»": "يوليا سميرنوفا \"راهن على نفسك\"",
      "B2B-диалогов в месяц": "حوارات B2B شهريا",
      "языков продаж": "لغات المبيعات",
      "ШАГ 02 ИЗ 07": "الخطوة 02 من 07",
      "ШАГ 07 ИЗ 07": "الخطوة 07 من 07",
      "AXCEND передаёт не просто контакты, а компании, которые поняли предложение, проявили интерес и согласились обсудить его с командой заказчика.": "لا تقوم AXCEND بنقل جهات الاتصال فحسب، بل تقوم بنقل الشركات التي فهمت الاقتراح وأبدت اهتمامًا ووافقت على مناقشته مع فريق العميل.",
      "AXCEND выстраивает полный цикл B2B-продаж: находим потенциальных клиентов, выходим на профильных руководителей, ведём переговоры, фиксируем результат в CRM и передаём готовых к сделке клиентов.": "تقوم AXCEND ببناء دورة كاملة من مبيعات B2B: حيث نقوم بالعثور على العملاء المحتملين، والاتصال بالمديرين المعنيين، والتفاوض، وتسجيل النتائج في نظام إدارة علاقات العملاء (CRM)، ونقل العملاء المستعدين للصفقة.",
      "AXCEND": "AXCEND",
      "B2B": "B2B",
