      "Азербайджан": "Azerbaycan",
      "Армения": "Ermenistan",
      "Банк / инвестпрограммы": "Banka / yatırım programları",
      "Внешний отдел продаж": "Dış satış departmanı",
      "База целевых компаний": "Hedef şirketler veritabanı",
      "Ведём холодный поиск и прозвон": "Soğuk arama yapıyoruz ve çağrı yapıyoruz",
      "Агентство «Мизель»": "Ajans \"Mizel\"",
      "Анна Бушева": "Anna Busheva",
