      "Выручка": "Hasılat",
      "Возвращаем в активные сделки": "Aktif işlemlere dön",
      "Внешний отдел B2B‑продаж": "Dış B2B satış ekibi",
      "Внешний отдел B2B-продаж · СНГ": "Harici B2B satış departmanı · CIS",
      "Гарантия": "Garanti",
      "Вы не хотите нанимать, обучать и контролировать менеджеров ради проверки нового направления.": "Yeni bir yönü test etmek için yöneticileri işe almak, eğitmek ve denetlemek istemezsiniz.",
      "ГАРАНТИЯ": "GARANTİ",
      "Выходим на клиентов, объясняем предложение, фиксируем реакцию, возражения и уровень заинтересованности.": "Müşterilerle iletişime geçiyoruz, teklifi açıklıyoruz, tepkileri, itirazları ve ilgi düzeyini kaydediyoruz.",
      "Гарантия в договоре": "Sözleşmedeki garanti",
      "Гарантия от 5% закрепляется в договоре": "Sözleşmede %5 oranında garanti sabittir",
      "Выходим на закупщиков и ЛПР": "Alıcılara ve karar vericilere ulaşıyoruz",
      "Выход на новый рынок": "Yeni bir pazara girmek",
      "ВОРОНКА ПРОДАЖ": "SATIŞ HUNİSİ",
      "входящие": "gelen kutusu",
      "Воронка продаж": "Satış hunisi",
      "Грузия": "Georgia",
      "Готовы обсуждать предметно": "Detaylı görüşmeye hazırız",
      "диалогов": "diyaloglar",
      "Гранд Сити": "Büyük Şehir",
      "Да, проект можно запустить под конкретную нишу или конкретный продукт без расширения охвата.": "Evet, belirli bir niş veya belirli bir ürün için kapsamı genişletilmeden proje başlatılabilir.",
      "Готовые сценарии под вашу задачу": "Göreviniz için hazır komut dosyaları",
      "дистрибуция": "dağıtım",
      "ДИСТРИБУЦИЯ": "DAĞITIM",
      "Да. Все контакты, статусы, заметки и записи переговоров остаются у заказчика.": "Evet. Tüm kişiler, durumlar, notlar ve konuşma kayıtları müşteride kalır.",
      "Доводим до подписанного договора": "İmzalı bir anlaşmaya varıyoruz",
      "Доводим до первой отгрузки": "İlk sevkiyata getiriyoruz",
      "Делаем допродажи по текущей базе": "Mevcut tabana göre ek satış yapıyoruz",
      "До 25–30% во встречу": "Toplantı başına %25-30'a kadar",
      "Дипломат (мужская одежда)": "Diplomat (erkek giyim)",
      "для рынка СНГ": "",
      "Диагностика продукта": "Ürün teşhisi",
      "Дальше →": "Devam →",
      "Дожимаем тёплых до сделки": "Anlaşmaya kadar sıcak olanlara basıyoruz",
      "ЖК «Левитан»": "Konut kompleksi \"Levitan\"",
      "Дошли до содержательного разговора": "Anlamlı bir sohbete ulaştık",
      "За счёт глубокого понимания продукта и точного подбора аудитории часть проектов даёт конверсию до 25–30% из целевых контактов во встречу.": "Ürünün derinlemesine anlaşılması ve hedef kitlenin hassas seçimi nedeniyle, bazı projeler hedef temaslardan toplantılara kadar %25-30'a varan dönüşüm elde ediyor.",
      "Заказчик видит, как рынок реагирует на продукт: какие аргументы работают, какие сегменты откликаются, что мешает интересу и где требуется усилить предложение.": "Müşteri, pazarın ürüne nasıl tepki verdiğini görür: hangi argümanların işe yaradığını, hangi segmentlerin yanıt verdiğini, neyin ilgiyi engellediğini ve teklifin nerede güçlendirilmesi gerektiğini.",
      "Заказчик получает не только контакты, но и понимание, какие сегменты рынка реагируют лучше, где интерес выше, а где предложение вызывает слабую реакцию.": "Müşteri yalnızca temas kurmakla kalmaz, aynı zamanda hangi pazar segmentlerinin daha iyi yanıt verdiği, ilginin nerede daha yüksek olduğu ve teklifin nerede zayıf tepkiye neden olduğu konusunda da bilgi sahibi olur.",
      "Заранее зафиксированные критерии релевантности компании, подтверждённого интереса и засчитываемой встречи.": "Şirket ilgisi, onaylanmış ilgi ve sayılabilir toplantı için önceden belirlenmiş kriterler.",
      "Доктор Андрей Баранов": "Dr.Andrey Baranov",
