      "Ищем компании, которым продукт действительно может быть нужен — не «по списку», а по релевантности и рыночным сигналам.": "Ürüne gerçekten ihtiyaç duyabilecek şirketleri arıyoruz - \"listeye göre\" değil, alaka düzeyine ve pazar sinyallerine göre.",
      "Используем профессиональные системы анализа рынка и цифрового поведения компаний. Отслеживаем активность бизнеса, изменения внутри компаний, закупочные сигналы, рост направлений, интерес к определённым решениям и другие признаки спроса. Так нам удается найти только те компании, для которых предложение действительно актуально.": "Şirketlerin pazarını ve dijital davranışlarını analiz etmek için profesyonel sistemler kullanıyoruz. İş faaliyetlerini, şirketler içindeki değişiklikleri, satın alma sinyallerini, alanlardaki büyümeyi, belirli çözümlere olan ilgiyi ve diğer talep işaretlerini izliyoruz. Bu şekilde yalnızca teklifin gerçekten ilgili olduğu şirketleri bulmayı başarıyoruz.",
      "Как клиенты движутся по воронке": "Müşteriler dönüşüm hunisinde nasıl hareket eder?",
