      "Мы продаём смыслами: разбираемся в продукте, ведём содержательный разговор с ЛПР и доводим до встречи, а не до отметки в отчёте.": "Anlamlı bir şekilde satış yapıyoruz: Ürünü anlıyoruz, karar vericiyle anlamlı bir konuşma yapıyoruz ve bunu raporda bir noktaya kadar değil, bir toplantıya getiriyoruz.",
      "Находим дилеров, оптовиков, торговые дома": "Bayileri, toptancıları, ticari evleri buluyoruz",
