      "Находим первых клиентов и партнёров": "İlk müşterilerimizi ve ortaklarımızı buluyoruz",
      "Назначаем встречу с вашей командой и передаём контекст: кто клиент, в чём интерес, какие вопросы возникли.": "Ekibinizle bir toplantı ayarlıyoruz ve bağlamı aktarıyoruz: müşterinin kim olduğu, ilginin ne olduğu, hangi soruların ortaya çıktığı.",
      "Наши менеджеры не работают по шаблону. В этом одно из ключевых отличий AXCEND. Благодаря опыту в консалтинге и B2B продажах наши менеджеры понимают как устроен рынок, разбираются даже в сложных продуктах, четко понимая интересы бизнеса, постепенно доводя контакт до готовности к встрече с заказчиком.": "Yöneticilerimiz bir şablona göre çalışmıyor. AXCEND arasındaki temel farklardan biri de budur. Danışmanlık ve B2B satış deneyimi sayesinde yöneticilerimiz pazarın nasıl çalıştığını anlıyor, karmaşık ürünleri bile anlıyor, işin çıkarlarını net bir şekilde anlıyor ve müşteriyle toplantıya hazırlık için yavaş yavaş iletişim kuruyor.",
      "ОАЭ": "BAE",
      "Нужны встречи с клиентами, а не отчёт о звонках": "Raporlara değil, müşterilerle toplantılara ihtiyacımız var",
      "Нужны новые B2B-клиенты, но нет сильной команды продаж": "Yeni B2B müşterilere ihtiyaç var ancak güçlü bir satış ekibi yok",
      "Нужна база с вероятностью интереса, а не просто список": "Sadece bir listeye değil, ilgi olasılığı olan bir veritabanına ihtiyacımız var",
      "Не случайный список компаний, а отобранная база организаций, которым продукт заказчика может быть релевантен по отрасли, размеру, географии, роли и признакам возможной потребности.": "Rastgele bir şirket listesi değil, müşterinin ürününün sektör, büyüklük, coğrafya, rol ve olası ihtiyaç belirtilerine göre ilgili olabileceği kuruluşların seçilmiş bir veritabanı.",
