      "Передаётся информация: кто заинтересовался, в чём причина интереса, какие вопросы возникли, какие возражения были озвучены и что важно учесть на встрече.": "Bilgi aktarılır: Kim ilgileniyor, ilginin nedeni nedir, hangi sorular ortaya çıktı, hangi itirazlar dile getirildi ve toplantıda nelerin dikkate alınması önemli.",
      "Перед стартом продаж изучаем рынок, конкурентов и целевую аудиторию. Смотрим, какие компании нуждаются в данном продукте, как сейчас продают аналогичные решения и какие аргументы сильнее всего работают в переговорах.": "Satışa başlamadan önce pazarı, rakipleri ve hedef kitleyi inceliyoruz. Hangi şirketlerin bu ürüne ihtiyacı olduğuna, benzer çözümleri şu anda nasıl sattıklarına ve müzakerelerde hangi argümanların en güçlü şekilde işe yaradığına bakıyoruz.",
      "Перед контактом с рынком нужно понять продукт, экономику сделки, аргументы для руководителей и возможные возражения.": "Piyasayla iletişime geçmeden önce ürünü, işlemin ekonomisini, yöneticilerin argümanlarını ve olası itirazları anlamalısınız.",
