      "Показываем, какие сегменты реагируют лучше, где слабая база, где нужно усилить предложение или аргументацию.": "Hangi kesimlerin daha iyi yanıt verdiğini, tabanın nerede zayıf olduğunu ve önerinin veya argümanın nerede güçlendirilmesi gerektiğini gösteriyoruz.",
