      "ЧТО ВЫ ПОЛУЧАЕТЕ": "NE ALABİLİRSİNİZ",
      "Юлия Смирнова «Ставки на себя»": "Yulia Smirnova “Kendinize Bahis Yapın”",
      "AXCEND передаёт не просто контакты, а компании, которые поняли предложение, проявили интерес и согласились обсудить его с командой заказчика.": "AXCEND sadece kişileri değil, teklifi anlayan, ilgi gösteren ve müşterinin ekibiyle konuyu görüşmeyi kabul eden şirketleri de aktarır.",
      "AXCEND выстраивает полный цикл B2B-продаж: находим потенциальных клиентов, выходим на профильных руководителей, ведём переговоры, фиксируем результат в CRM и передаём готовых к сделке клиентов.": "AXCEND tam bir B2B satış döngüsü oluşturur: potansiyel müşterileri buluyoruz, ilgili yöneticilerle iletişime geçiyoruz, pazarlık yapıyoruz, sonuçları CRM'ye kaydediyoruz ve anlaşmaya hazır müşterileri transfer ediyoruz.",
      "B2B-диалогов в месяц": "Aylık B2B diyalogları",
