      "Вы не хотите нанимать, обучать и контролировать менеджеров ради проверки нового направления.": "새로운 방향을 테스트하기 위해 관리자를 고용, 교육, 감독하고 싶지는 않습니다.",
      "Выходим на клиентов, объясняем предложение, фиксируем реакцию, возражения и уровень заинтересованности.": "우리는 고객에게 연락하고, 제안을 설명하고, 반응, 반대 및 관심 수준을 기록합니다.",
      "ГАРАНТИЯ": "보장하다",
