      "Дальше →": "계속 →",
      "Да, проект можно запустить под конкретную нишу или конкретный продукт без расширения охвата.": "예, 범위를 확장하지 않고도 특정 틈새 시장이나 특정 제품에 대한 프로젝트를 시작할 수 있습니다.",
      "Делаем допродажи по текущей базе": "우리는 현재 기반을 기반으로 상향 판매합니다.",
      "Да. Все контакты, статусы, заметки и записи переговоров остаются у заказчика.": "예. 모든 연락처, 상태, 메모 및 대화 녹음은 고객에게 그대로 유지됩니다.",
      "Гарантия от 5% закрепляется в договоре": "계약서에는 5%의 보증이 고정되어 있습니다.",
      "Готовы обсуждать предметно": "자세하게 논의할 준비가 되어있습니다",
      "Гарантия в договоре": "계약상의 보증",
      "Готовые сценарии под вашу задачу": "귀하의 작업을 위해 미리 만들어진 스크립트",
      "диалогов": "대화",
      "дистрибуция": "분포",
      "ДИСТРИБУЦИЯ": "분포",
      "Дипломат (мужская одежда)": "외교관(남성복)",
      "До 25–30% во встречу": "회의당 최대 25~30%",
      "Дожимаем тёплых до сделки": "우리는 거래가 이루어질 때까지 따뜻한 것을 누른다",
      "Доводим до первой отгрузки": "우리는 첫 번째 배송으로 가져옵니다",
      "Доводим до подписанного договора": "우리는 서명된 계약을 체결합니다",
      "Диагностика продукта": "제품 진단",
      "Доктор Андрей Баранов": "안드레이 바라노프 박사",
      "для рынка СНГ": "",
      "Заказчик видит, как рынок реагирует на продукт: какие аргументы работают, какие сегменты откликаются, что мешает интересу и где требуется усилить предложение.": "고객은 시장이 제품에 어떻게 반응하는지, 즉 어떤 주장이 효과적인지, 어떤 세그먼트가 반응하는지, 무엇이 관심을 방해하는지, 제안이 강화되어야 하는 부분을 확인합니다.",
      "Доктор Хорошев": "코로셰프 박사",
      "из": "~에서",
      "Заранее зафиксированные критерии релевантности компании, подтверждённого интереса и засчитываемой встречи.": "회사 관련성, 확인된 관심 및 셀 수 있는 회의에 대한 사전 고정 기준.",
      "ЖК «Левитан»": "주거단지 '레비탄'",
      "Закрываем пилотные сделки": "우리는 파일럿 거래를 마감하고 있습니다",
      "Дошли до содержательного разговора": "우리는 의미있는 대화를 나눴습니다",
      "Закрываем входящие заявки": "들어오는 요청을 닫는 중",
      "За счёт глубокого понимания продукта и точного подбора аудитории часть проектов даёт конверсию до 25–30% из целевых контактов во встречу.": "제품에 대한 깊은 이해와 청중의 정확한 선택으로 인해 일부 프로젝트는 대상 접촉에서 회의로 최대 25-30%의 전환을 달성합니다.",
      "Заказчик получает не только контакты, но и понимание, какие сегменты рынка реагируют лучше, где интерес выше, а где предложение вызывает слабую реакцию.": "고객은 연락을 받을 뿐만 아니라 어떤 시장 부문이 더 잘 반응하는지, 어느 부분이 관심이 더 높은지, 제안이 약한 반응을 일으키는 부분에 대한 이해도 받습니다.",
      "исходящие": "나가는",
      "Казахстан": "카자흐스탄",
      "Калькулятор": "계산기",
      "ИСХОДЯЩИЕ": "보낼 편지함",
      "Инкор Медицинские Сертификаты": "인코 의료 증명서",
      "Как строится работа": "작업이 어떻게 구성되어 있는지",
      "Как клиенты движутся по воронке": "고객이 퍼널을 통해 이동하는 방법",
      "Используем профессиональные системы анализа рынка и цифрового поведения компаний. Отслеживаем активность бизнеса, изменения внутри компаний, закупочные сигналы, рост направлений, интерес к определённым решениям и другие признаки спроса. Так нам удается найти только те компании, для которых предложение действительно актуально.": "우리는 기업의 시장 및 디지털 행동을 분석하기 위해 전문 시스템을 사용합니다. 우리는 비즈니스 활동, 회사 내 변화, 구매 신호, 영역 성장, 특정 솔루션에 대한 관심 및 기타 수요 징후를 모니터링합니다. 이러한 방식으로 우리는 제안이 실제로 관련이 있는 회사만 찾을 수 있습니다.",
      "Ищем компании, которым продукт действительно может быть нужен — не «по списку», а по релевантности и рыночным сигналам.": "우리는 \"목록\"이 아닌 관련성과 시장 신호를 기준으로 실제로 제품이 필요할 수 있는 회사를 찾고 있습니다.",
      "Казахстан, Узбекистан, Южная Корея, Турция, Армения, Кыргызстан и сопредельные рынки СНГ.": "카자흐스탄, 우즈베키스탄, 한국, 투르키예, 아르메니아, 키르기스스탄 및 인근 CIS 시장.",
