      "Цель работы — передача вашей команде компаний, готовых к предметному разговору, а не количество контактов.": "작업의 목표는 연락처 수가 아닌 실질적인 대화가 가능한 회사를 팀에 제공하는 것입니다.",
      "У нас входящие сыплются, а отвечать некому. Плюс по холодке надо звонить — а сил на это нет. Заберите всё, верните уже закрытые сделки.": "받은편지함이 넘쳐나는데 응답할 사람이 없습니다. 게다가 추울 때 전화를 해야 하는데 그럴 힘도 없어요. 모든 것을 취하고 이미 종료된 트랜잭션을 반환합니다.",
      "Формируем базу клиентов, очищаем её от нерелевантных компаний и приоритизируем контакты.": "우리는 고객 기반을 형성하고, 관련 없는 회사를 제거하고 연락처를 우선적으로 처리합니다.",
      "Что входит в гарантию?": "보증에는 무엇이 포함되나요?",
      "Шаг": "단계",
      "Что вы получаете": "무엇을 얻나요?",
      "ЧТО ВЫ ПОЛУЧАЕТЕ": "당신은 무엇을 얻나요?",
      "ШАГ 02 ИЗ 07": "07단계 중 02단계",
