      "ШАГ 01 ИЗ 07": "07단계 중 01단계",
      "Энергетика": "에너지",
      "Чем отличаетесь от классического колл-центра?": "기존 콜센터와 어떻게 다릅니까?",
      "Южная Корея": "대한민국",
      "ШАГ 03 ИЗ 07": "07단계 중 03단계",
      "ШАГ 04 ИЗ 07": "07단계 중 04단계",
