      "Эбру": "에브루",
      "ШАГ 07 ИЗ 07": "07/07단계",
      "ШАГ 06 ИЗ 07": "07단계 중 06단계",
      "AXCEND передаёт не просто контакты, а компании, которые поняли предложение, проявили интерес и согласились обсудить его с командой заказчика.": "AXCEND는 단순한 연락이 아닌 제안을 이해하고 관심을 보인 회사가 고객 팀과 논의하기로 합의했습니다.",
      "AXCEND выстраивает полный цикл B2B-продаж: находим потенциальных клиентов, выходим на профильных руководителей, ведём переговоры, фиксируем результат в CRM и передаём готовых к сделке клиентов.": "AXCEND는 B2B 판매의 전체 주기를 구축합니다. 잠재 고객을 찾고, 관련 관리자에게 연락하고, 협상하고, CRM에 결과를 기록하고, 거래 준비가 된 고객을 전달합니다.",
      "Юлия Смирнова «Ставки на себя»": "Yulia Smirnova \"자신에게 베팅하세요\"",
      "языков продаж": "판매 언어",
      "B2B-диалогов в месяц": "월별 B2B 대화",
      "AXCEND": "AXCEND",
      "B2B": "B2B",
      "CRM": "CRM",
      "FAQ": "FAQ",
      "WIN-BACK": "WIN-BACK",
      "win-back": "win-back",
