      "Роль ЛПР": "의사결정자 역할",
      "Выходим на людей, которые могут обсуждать задачу и влиять на решение.": "문제를 논의하고 의사결정에 영향을 줄 수 있는 사람에게 접근합니다.",
      "Потребность": "니즈",
